/**
 * Output Generator Module
 *
 * Handles generation of build output files:
 * - Client runtime scripts (app.js, client.js, router.js, prefetch.js)
 * - Build manifest
 * - Service worker
 * - Redirects file
 * - Static asset copying
 */
import { serverLogger as logger } from "../../../utils/index.js";
import { dirname, join } from "../../../platform/compat/path/index.js";
import { generateServiceWorker } from "../../../server/build-service-worker.js";
import { generateProdHydrationModule, getProdHydrationModulePath, } from "../../../html/hydration-script-builder/prod-scripts.js";
import { copyStaticAssets } from "../asset-generation.js";
import { generateAppModule, generateClientModule, generatePrefetchScript, generateRouterScript, } from "../client-runtime.js";
import { generateLocalReleaseAssetManifest } from "../local-release-assets.js";
import { generateManifest, generateRedirects } from "../manifest.js";
/**
 * Generate client runtime scripts
 */
export async function generateClientScripts(adapter, outputDir, dryRun) {
    logger.debug("Copying client scripts...");
    if (dryRun)
        return;
    await writeOutputFile(adapter, join(outputDir, "_veryfront/app.js"), generateAppModule());
    await writeOutputFile(adapter, join(outputDir, "_veryfront/client.js"), await generateClientModule());
    await writeOutputFile(adapter, join(outputDir, "_veryfront/router.js"), await generateRouterScript(adapter));
    await writeOutputFile(adapter, join(outputDir, "_veryfront/prefetch.js"), await generatePrefetchScript(adapter));
    const hydrationRuntime = generateProdHydrationModule();
    await writeOutputFile(adapter, join(outputDir, "_veryfront/hydration-runtime.js"), hydrationRuntime);
    await writeOutputFile(adapter, join(outputDir, getProdHydrationModulePath().slice(1)), hydrationRuntime);
}
async function writeOutputFile(adapter, path, content) {
    await adapter.fs.mkdir(dirname(path), { recursive: true });
    await adapter.fs.writeFile(path, content);
}
/**
 * Generate manifest and service worker
 */
export async function generateManifestAndServiceWorker(options) {
    const { adapter, outputDir, routes, appRoutes, stats, enableSplitting, enablePrefetch, enableCompression, chunkManifest, dryRun, } = options;
    const manifest = generateManifest({
        routes,
        appRoutes,
        stats,
        enableSplitting,
        enablePrefetch,
        enableCompression,
        chunkManifest,
    });
    if (dryRun)
        return;
    await adapter.fs.writeFile(join(outputDir, "_veryfront/manifest.json"), JSON.stringify(manifest, null, 2));
    await adapter.fs.writeFile(join(outputDir, "sw.js"), generateServiceWorker(manifest));
}
/**
 * Generate redirects file
 */
export async function generateRedirectsFile(adapter, outputDir, dryRun) {
    if (dryRun)
        return;
    await adapter.fs.writeFile(join(outputDir, "_redirects"), generateRedirects());
}
/**
 * Copy static assets and return statistics
 */
export function copyAssets(adapter, projectDir, outputDir, dryRun) {
    return copyStaticAssets(adapter, projectDir, outputDir, dryRun);
}
/**
 * Generate all output files
 */
export async function generateAllOutputs(options) {
    const { adapter, projectDir, outputDir, dryRun, stats, config, releaseAssetManifest } = options;
    await generateClientScripts(adapter, outputDir, dryRun);
    if (releaseAssetManifest === undefined) {
        await generateLocalReleaseAssetManifest({
            adapter,
            projectDir,
            outputDir,
            dryRun,
            config,
        });
    }
    const assetStats = await copyAssets(adapter, projectDir, outputDir, dryRun);
    stats.assets = assetStats.assets;
    stats.totalSize += assetStats.totalSize;
    await generateManifestAndServiceWorker(options);
    await generateRedirectsFile(adapter, outputDir, dryRun);
}
